 )

 // newServeCmd creates the Cobra command for starting the MCP server.
 func newServeCmd() *cobra.Command {
 	var (
 		debugMode   bool
 		enableOAuth bool

 		// Transport options
 		transport       string
 		httpAddr        string
 		sseEndpoint     string
 		messageEndpoint string
 		httpEndpoint    string

 		// Observability
 		metricsAddr string

 		// Tenancy
 		tenancyMode   string
 		staticTenants string
 	)

 	cmd := &cobra.Command{
 		Use:   "serve",
 		Short: "Start the MCP Prometheus server",
 		Long: `Start the MCP Prometheus server to provide tools for interacting
 with Prometheus metrics via the Model Context Protocol.

 Supports multiple transport types:
   - stdio: Standard input/output (default)
   - sse: Server-Sent Events over HTTP
   - streamable-http: Streamable HTTP transport

 Environment Variables:
   PROMETHEUS_URL      - Optional: Prometheus server URL (takes precedence over tool parameters)
   PROMETHEUS_ORGID    - Optional: Organization ID for multi-tenant setups (takes precedence over tool parameters)
   PROMETHEUS_USERNAME - Optional: Basic auth username
   PROMETHEUS_PASSWORD - Optional: Basic auth password
   PROMETHEUS_TOKEN    - Optional: Bearer token for authentication

 OAuth 2.1 (when --enable-oauth is set):
   MCP_OAUTH_ISSUER              - OAuth issuer URL (required)
   MCP_OAUTH_ENCRYPTION_KEY      - AES-256-GCM key for token encryption (base64, required)
   OAUTH_STORAGE                 - Storage backend: memory (default) or valkey
   VALKEY_URL                    - Valkey connection URL (when OAUTH_STORAGE=valkey)
   DEX_ISSUER_URL                - Dex OIDC issuer URL (required)
   DEX_CLIENT_ID                 - Dex OAuth client ID (required)
   DEX_CLIENT_SECRET             - Dex OAuth client secret (required)
   DEX_REDIRECT_URL              - OAuth redirect URL (required)

 Tenancy (when --enable-oauth is set):
   --tenancy-mode                - grafana-organization (default) or static
   --static-tenants              - Comma-separated tenant IDs for all users (static mode)
   TENANCY_STATIC_GROUP_MAP      - JSON map of group→[tenant IDs] for group-mapping (static mode)

 If PROMETHEUS_URL or PROMETHEUS_ORGID environment variables are not set,
 they can be provided as parameters to individual tool calls.`,
 		RunE: func(cmd *cobra.Command, args []string) error {
 			return runServe(transport, debugMode, enableOAuth,
 				httpAddr, sseEndpoint, messageEndpoint, httpEndpoint,
 				metricsAddr, tenancyMode, staticTenants)
 		},
 	}

 	// Add flags for configuring the server
 	cmd.Flags().BoolVar(&debugMode, "debug", false, "Enable debug logging (default: false)")
 	cmd.Flags().BoolVar(&enableOAuth, "enable-oauth", false, "Enable OAuth 2.1 authentication (requires MCP_OAUTH_* and DEX_* env vars; sse/streamable-http only)")

 	// Transport flags
 	cmd.Flags().StringVar(&transport, "transport", "stdio", "Transport type: stdio, sse, or streamable-http")
 	cmd.Flags().StringVar(&httpAddr, "http-addr", ":8080", "HTTP server address (for sse and streamable-http transports)")
 	cmd.Flags().StringVar(&sseEndpoint, "sse-endpoint", "/sse", "SSE endpoint path (for sse transport)")
 	cmd.Flags().StringVar(&messageEndpoint, "message-endpoint", "/message", "Message endpoint path (for sse transport)")
 	cmd.Flags().StringVar(&httpEndpoint, "http-endpoint", "/mcp", "HTTP endpoint path (for streamable-http transport)")
 	cmd.Flags().StringVar(&metricsAddr, "metrics-addr", ":9091", "Address for the observability HTTP server (/metrics, /healthz, /readyz). Set to empty string to disable.")

 	// Tenancy flags (only relevant when --enable-oauth is set)
 	cmd.Flags().StringVar(&tenancyMode, "tenancy-mode", string(tenancy.ModeGrafanaOrganization),
 		"Tenancy resolution mode when OAuth is enabled: grafana-organization or static")
 	cmd.Flags().StringVar(&staticTenants, "static-tenants", "",
 		"Comma-separated Mimir tenant IDs for all authenticated users (--tenancy-mode=static only)")

 	return cmd
 }

 // runServe contains the main server logic with support for multiple transports
 func runServe(transport string, debugMode bool, enableOAuth bool,
 	httpAddr, sseEndpoint, messageEndpoint, httpEndpoint string,
 	metricsAddr string, tenancyMode string, staticTenants string) error {

 	// Create the unified structured logger.
 	logLevel := slog.LevelInfo
 	if debugMode {
 		logLevel = slog.LevelDebug
 	}
 	logger := slog.New(slog.NewTextHandler(os.Stderr, &slog.HandlerOptions{Level: logLevel}))

 	// Setup graceful shutdown - listen for both SIGINT and SIGTERM
 	shutdownCtx, cancel := signal.NotifyContext(context.Background(),
 		os.Interrupt, syscall.SIGTERM)
 	defer cancel()

 	// Collect server context options; OAuth may append more below.
 	serverOpts := []server.ServerOption{
 		server.WithSlogLogger(logger),
 	}

 	// OAuth 2.1 setup (SSE and streamable-http transports only).
 	var oauthHandler *handler.Handler
 	if enableOAuth {
 		if transport == "stdio" {
 			return fmt.Errorf("--enable-oauth is not supported with stdio transport")
 		}

 		oauthCfg := oauth.ConfigFromEnv()
 		h, cleanup, err := oauth.NewHandler(shutdownCtx, oauthCfg, logger)
 		if err != nil {
 			return fmt.Errorf("failed to initialise OAuth handler: %w", err)
 		}
 		defer cleanup()
 		oauthHandler = h

 		// Parse static group map from env: JSON object of group → [tenant IDs].
 		var groupMap map[string][]string
 		if raw := os.Getenv("TENANCY_STATIC_GROUP_MAP"); raw != "" {
 			if err := json.Unmarshal([]byte(raw), &groupMap); err != nil {
 				return fmt.Errorf("TENANCY_STATIC_GROUP_MAP: invalid JSON: %w", err)
 			}
 		}

 		tenancyResolver, err := tenancy.NewResolverForMode(
 			tenancy.Mode(tenancyMode),
 			parseTenants(staticTenants),
 			groupMap,
 		)
 		if err != nil {
 			return fmt.Errorf("failed to create tenancy resolver: %w", err)
 		}

 		serverOpts = append(serverOpts,
 			server.WithOAuthEnabled(true),
 			server.WithTenancyResolver(tenancyResolver),
 		)

 		logger.Info("OAuth 2.1 authentication enabled", "tenancy_mode", tenancyMode)
 	}

 	// Create server context
 	serverContext, err := server.NewServerContext(shutdownCtx, serverOpts...)
 	if err != nil {
 		return fmt.Errorf("failed to create server context: %w", err)
 	}
 	defer func() {
 		if err := serverContext.Shutdown(); err != nil {
 			logger.Error("Error during server context shutdown", "error", err)
 		}
 	}()

 	// Log configuration
 	config := serverContext.PrometheusConfig()
 	authMethod := "none"
 	if config.Username != "" && config.Password != "" {
 		authMethod = fmt.Sprintf("basic (username: %s)", config.Username)
 	} else if config.Token != "" {
 		authMethod = "bearer token"
 	}
 	logger.Info("Prometheus configuration",
 		"url", config.URL,
 		"auth", authMethod,
 		"org_id", config.OrgID,
 	)

 	// Initialise observability (metrics + tracing)
 	metrics := observability.NewMetrics()
 	health := &observability.Health{}

 	tp, shutdownTracer, err := observability.NewTracerProvider(shutdownCtx, logger)
 	if err != nil {
 		return fmt.Errorf("failed to initialise OTel tracer: %w", err)
 	}
 	defer func() {
 		if err := shutdownTracer(context.Background()); err != nil {
 			logger.Error("Error flushing OTel spans", "error", err)
 		}
 	}()

 	inst := observability.NewInstrumentor(metrics, tp)

 	// Start observability HTTP server (/metrics, /healthz, /readyz) unless disabled.
 	// Listen is called synchronously so a port-conflict error fails startup immediately.
 	if metricsAddr != "" {
 		mux := observability.NewServer(metrics, health)
 		ln, err := observability.Listen(metricsAddr)
 		if err != nil {
 			return fmt.Errorf("failed to bind observability server: %w", err)
 		}
 		logger.Info("Observability server listening", "addr", metricsAddr)
 		go func() {
 			if err := observability.Serve(shutdownCtx, ln, mux); err != nil {
 				logger.Error("Observability server stopped", "error", err)
 			}
 		}()
 	}

 	// Create MCP server
 	mcpSrv := mcpserver.NewMCPServer("mcp-prometheus", rootCmd.Version,
 		mcpserver.WithToolCapabilities(true),
 		mcpserver.WithInputSchemaValidation(),
 	)

 	// Register Prometheus tools with observability instrumentation
 	if err := prometheus.RegisterPrometheusTools(mcpSrv, serverContext, inst.Wrap); err != nil {
 		return fmt.Errorf("failed to register Prometheus tools: %w", err)
 	}

 	// Mark server as ready after all tools are registered
 	health.SetReady(true)

 	logger.Info("Starting MCP Prometheus server", "transport", transport)

 	// Start the appropriate server based on transport type
 	switch transport {
 	case "stdio":
 		return runStdioServer(mcpSrv, logger)
 	case "sse":
 		return runSSEServer(mcpSrv, httpAddr, sseEndpoint, messageEndpoint, shutdownCtx, logger, oauthHandler)
 	case "streamable-http":
 		return runStreamableHTTPServer(mcpSrv, httpAddr, httpEndpoint, shutdownCtx, logger, oauthHandler)
 	default:
 		return fmt.Errorf("unsupported transport type: %s (supported: stdio, sse, streamable-http)", transport)
 	}
 }

 // parseTenants splits a comma-separated tenant string into a trimmed, non-empty slice.
 func parseTenants(s string) []string {
 	if s == "" {
 		return nil
 	}
 	parts := strings.Split(s, ",")
 	result := make([]string, 0, len(parts))
 	for _, p := range parts {
 		if p = strings.TrimSpace(p); p != "" {
 			result = append(result, p)
 		}
 	}
 	return result
 }

 // serveHTTPWithShutdown binds a TCP listener, serves with the given handler, and
 // shuts down gracefully when ctx is cancelled.
 func serveHTTPWithShutdown(ctx context.Context, addr string, handler http.Handler) error {
 	ln, err := net.Listen("tcp", addr)
 	if err != nil {
 		return fmt.Errorf("listen %s: %w", addr, err)
 	}

 	srv := &http.Server{
 		Handler:           handler,
 		ReadHeaderTimeout: 10 * time.Second,
 	}

 	errCh := make(chan error, 1)
 	go func() {
 		if err := srv.Serve(ln); err != nil && err != http.ErrServerClosed {
 			errCh <- err
 		}
 		close(errCh)
 	}()

 	select {
 	case <-ctx.Done():
 		shutdownCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
 		defer cancel()
 		if err := srv.Shutdown(shutdownCtx); err != nil {
 			return fmt.Errorf("shutdown: %w", err)
 		}
 		return nil
 	case err := <-errCh:
 		return err
 	}
 }

 // registerOAuthRoutes mounts all OAuth 2.1 endpoints onto mux and wraps each
 // MCP handler with ValidateToken middleware.
 func registerOAuthRoutes(mux *http.ServeMux, h *handler.Handler, mcpPath string, mcpHandlers map[string]http.Handler) {
 	h.RegisterAuthorizationServerMetadataRoutes(mux)
 	h.RegisterProtectedResourceMetadataRoutes(mux, mcpPath)
 	mux.HandleFunc("/oauth/authorize", h.ServeAuthorization)
 	mux.HandleFunc("/oauth/callback", h.ServeCallback)
 	mux.HandleFunc("/oauth/token", h.ServeToken)
 	mux.HandleFunc("/oauth/register", h.ServeClientRegistration)
 	mux.HandleFunc("/oauth/revoke", h.ServeTokenRevocation)
 	for path, handler := range mcpHandlers {
 		mux.Handle(path, h.ValidateToken(handler))
 	}
 }

 // runStdioServer runs the server with STDIO transport
 func runStdioServer(mcpSrv *mcpserver.MCPServer, logger *slog.Logger) error {
 	// Start the server in a goroutine so we can handle shutdown signals
 	serverDone := make(chan error, 1)
 	go func() {
 		defer close(serverDone)
 		if err := mcpserver.ServeStdio(mcpSrv); err != nil {
 			serverDone <- err
 		}
 	}()

 	// Wait for server completion
 	if err := <-serverDone; err != nil {
 		return fmt.Errorf("server stopped with error: %w", err)
 	}
 	logger.Info("Server stopped normally")

 	logger.Info("Server gracefully stopped")
 	return nil
 }

 // runSSEServer runs the server with SSE transport.
 // When oauthHandler is non-nil, a custom HTTP mux is built with OAuth 2.1
 // endpoints and the SSE/message paths are protected with ValidateToken.
 func runSSEServer(mcpSrv *mcpserver.MCPServer, addr, sseEndpoint, messageEndpoint string, ctx context.Context, logger *slog.Logger, oauthHandler *handler.Handler) error {
 	logger.Debug("SSE server configuration", "addr", addr, "sse_endpoint", sseEndpoint, "message_endpoint", messageEndpoint, "oauth", oauthHandler != nil)

 	sseServer := mcpserver.NewSSEServer(mcpSrv,
 		mcpserver.WithSSEEndpoint(sseEndpoint),
 		mcpserver.WithMessageEndpoint(messageEndpoint),
 	)

 	logger.Info("SSE server starting", "addr", addr, "sse_endpoint", sseEndpoint, "message_endpoint", messageEndpoint)

 	if oauthHandler != nil {
 		// OAuth path: custom mux with protected MCP routes.
 		mux := http.NewServeMux()
 		registerOAuthRoutes(mux, oauthHandler, sseEndpoint, map[string]http.Handler{
 			sseEndpoint:     sseServer.SSEHandler(),
 			messageEndpoint: sseServer.MessageHandler(),
 		})
 		logger.Info("OAuth 2.1 endpoints mounted", "path", "/oauth/*")
 		return serveHTTPWithShutdown(ctx, addr, mux)
 	}

 	// No OAuth: use the SSE server's built-in Start/Shutdown lifecycle.
 	serverDone := make(chan error, 1)
 	go func() {
 		defer close(serverDone)
 		if err := sseServer.Start(addr); err != nil {
 			serverDone <- err
 		}
 	}()

 	select {
 	case <-ctx.Done():
 		logger.Info("Shutdown signal received, stopping SSE server")
 		shutdownCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
 		defer cancel()
 		if err := sseServer.Shutdown(shutdownCtx); err != nil {
 			return fmt.Errorf("error shutting down SSE server: %w", err)
 		}
 	case err := <-serverDone:
 		if err != nil {
 			return fmt.Errorf("SSE server stopped with error: %w", err)
 		}
 	}

 	logger.Info("SSE server gracefully stopped")
 	return nil
 }

 // runStreamableHTTPServer runs the server with Streamable HTTP transport.
 // When oauthHandler is non-nil, MCP requests are protected with ValidateToken.
 func runStreamableHTTPServer(mcpSrv *mcpserver.MCPServer, addr, endpoint string, ctx context.Context, logger *slog.Logger, oauthHandler *handler.Handler) error {
 	httpServer := mcpserver.NewStreamableHTTPServer(mcpSrv,
 		mcpserver.WithEndpointPath(endpoint),
 	)

 	logger.Info("Streamable HTTP server starting", "addr", addr, "endpoint", endpoint)

 	if oauthHandler != nil {
 		// OAuth path: custom mux with protected MCP route.
 		mux := http.NewServeMux()
 		registerOAuthRoutes(mux, oauthHandler, endpoint, map[string]http.Handler{
 			endpoint: httpServer,
 		})
 		logger.Info("OAuth 2.1 endpoints mounted", "path", "/oauth/*")
 		return serveHTTPWithShutdown(ctx, addr, mux)
 	}

 	// No OAuth: use the streamable HTTP server's built-in lifecycle.
 	serverDone := make(chan error, 1)
 	go func() {
 		defer close(serverDone)
 		if err := httpServer.Start(addr); err != nil {
 			serverDone <- err
 		}
 	}()

 	select {
 	case <-ctx.Done():
 		logger.Info("Shutdown signal received, stopping HTTP server")
 		shutdownCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
 		defer cancel()
 		if err := httpServer.Shutdown(shutdownCtx); err != nil {
 			return fmt.Errorf("error shutting down HTTP server: %w", err)
 		}
 	case err := <-serverDone:
 		if err != nil {
 			return fmt.Errorf("HTTP server stopped with error: %w", err)
 		}
 	}

 	logger.Info("HTTP server gracefully stopped")
 	return nil
 }

diff --git a/app/internal/oauth/setup.go b/app/internal/oauth/setup.go
index 0000000..0000000 100644
--- a/app/internal/oauth/setup.go
+++ b/app/internal/oauth/setup.go
@@ -1,241 +1,241 @@
 package oauth

 import (
 	"context"
 	"crypto/tls"
 	"encoding/base64"
 	"fmt"
 	"log/slog"
 	"os"
 	"strings"
 	"time"

 	mcpoauth "github.com/giantswarm/mcp-oauth"
 	"github.com/giantswarm/mcp-oauth/handler"
 	"github.com/giantswarm/mcp-oauth/providers"
 	"github.com/giantswarm/mcp-oauth/providers/dex"
 	mcpoidc "github.com/giantswarm/mcp-oauth/providers/oidc"
 	"github.com/giantswarm/mcp-oauth/security"
 	"github.com/giantswarm/mcp-oauth/storage"
 	"github.com/giantswarm/mcp-oauth/storage/memory"
 	"github.com/giantswarm/mcp-oauth/storage/valkey"
 )

 // Config holds all configuration needed to start the OAuth 2.1 Authorization Server.
 // Every field maps directly to an environment variable so the server can be configured
 // without code changes.
 type Config struct {
 	// Issuer is the public base URL of this MCP server (e.g. "https://mcp.example.com").
 	// Used as the OAuth issuer identifier and as the base for endpoint URLs.
 	Issuer string

 	// EncryptionKey is a 32-byte base64-encoded key used for AES-256-GCM token encryption.
 	// If empty, tokens are stored unencrypted (only suitable for development).
 	EncryptionKey string

 	// AllowPublicRegistration permits unauthenticated dynamic client registration.
 	// Set true for development / MCP Inspector; false for production.
 	AllowPublicRegistration bool

 	// StorageType selects the token store backend: "memory" (default) or "valkey".
 	StorageType string

 	// ValkeyURL is the Valkey/Redis address, e.g. "localhost:6379".
 	// Required when StorageType == "valkey".
 	ValkeyURL string

 	// ValkeyPassword is the optional Valkey authentication password.
 	ValkeyPassword string

 	// ValkeyTLS enables TLS for Valkey connections.
 	ValkeyTLS bool

 	// ValkeyKeyPrefix is an optional key namespace prefix (default: "mcp:").
 	ValkeyKeyPrefix string

 	// DexIssuerURL is the Dex OIDC issuer, e.g. "https://dex.example.com".
 	DexIssuerURL string

 	// DexClientID is the OAuth client ID registered in Dex.
 	DexClientID string

 	// DexClientSecret is the OAuth client secret registered in Dex.
 	DexClientSecret string

 	// DexRedirectURL is the callback URL registered in Dex,
 	// e.g. "https://mcp.example.com/oauth/callback".
 	DexRedirectURL string

 	// TrustedAudiences lists OAuth client IDs whose tokens are accepted for SSO.
 	// When an upstream aggregator (like muster) forwards a user's ID token,
 	// mcp-prometheus accepts it if the token's audience matches any entry here.
 	// Tokens must still be from the configured issuer (Dex) and cryptographically valid.
 	TrustedAudiences []string

 	// AllowPrivateURLs permits OIDC discovery against Dex instances whose hostname
 	// resolves to a private/internal IP address (e.g. dex.<mc>.<baseDomain> on a
 	// private management cluster). When true, the HTTP client used for OIDC
 	// discovery bypasses the built-in SSRF protection that normally blocks
 	// connections to RFC-1918 ranges.
 	//
 	// Set MCP_OAUTH_ALLOW_PRIVATE_URLS=true only in trusted internal environments
 	// where the Dex issuer URL uses internal DNS. TLS verification is still enforced.
 	AllowPrivateURLs bool
 }

 // envTrue is the string value that enables a boolean env var.
 const envTrue = "true"

 // storageTypeValkey selects the Valkey-backed token store via OAUTH_STORAGE.
 const storageTypeValkey = "valkey"

 // ConfigFromEnv builds a Config by reading the standard environment variables.
 func ConfigFromEnv() Config {
 	cfg := Config{
 		Issuer:                  os.Getenv("MCP_OAUTH_ISSUER"),
 		EncryptionKey:           os.Getenv("MCP_OAUTH_ENCRYPTION_KEY"),
 		AllowPublicRegistration: os.Getenv("MCP_OAUTH_ALLOW_PUBLIC_REGISTRATION") == envTrue,
 		StorageType:             os.Getenv("OAUTH_STORAGE"),
 		ValkeyURL:               os.Getenv("VALKEY_URL"),
 		ValkeyPassword:          os.Getenv("VALKEY_PASSWORD"),
 		ValkeyTLS:               os.Getenv("VALKEY_TLS_ENABLED") == envTrue,
 		ValkeyKeyPrefix:         os.Getenv("VALKEY_KEY_PREFIX"),
 		DexIssuerURL:            os.Getenv("DEX_ISSUER_URL"),
 		DexClientID:             os.Getenv("DEX_CLIENT_ID"),
 		DexClientSecret:         os.Getenv("DEX_CLIENT_SECRET"),
 		DexRedirectURL:          os.Getenv("DEX_REDIRECT_URL"),
 		AllowPrivateURLs:        os.Getenv("MCP_OAUTH_ALLOW_PRIVATE_URLS") == envTrue,
 	}
 	if v := os.Getenv("OAUTH_TRUSTED_AUDIENCES"); v != "" {
 		for _, a := range strings.Split(v, ",") {
 			if a = strings.TrimSpace(a); a != "" {
 				cfg.TrustedAudiences = append(cfg.TrustedAudiences, a)
 			}
 		}
 	}
 	return cfg
 }

 // NewHandler initialises the mcp-oauth Handler from the given Config.
 // It returns the handler and a cleanup function that must be called on shutdown
 // to flush and close the storage backend.
 func NewHandler(ctx context.Context, cfg Config, logger *slog.Logger) (*handler.Handler, func(), error) {
 	if cfg.Issuer == "" {
 		return nil, nil, fmt.Errorf("oauth: MCP_OAUTH_ISSUER must be set")
 	}
 	if cfg.DexIssuerURL == "" || cfg.DexClientID == "" || cfg.DexClientSecret == "" {
 		return nil, nil, fmt.Errorf("oauth: DEX_ISSUER_URL, DEX_CLIENT_ID, DEX_CLIENT_SECRET must all be set")
 	}
 	if cfg.DexRedirectURL == "" {
 		return nil, nil, fmt.Errorf("oauth: DEX_REDIRECT_URL must be set")
 	}

 	dexCfg := &dex.Config{
 		IssuerURL:    cfg.DexIssuerURL,
 		ClientID:     cfg.DexClientID,
 		ClientSecret: cfg.DexClientSecret,
 		RedirectURL:  cfg.DexRedirectURL,
 		// Request groups so the tenant resolver can match GrafanaOrganization RBAC.
 		Scopes: []string{"openid", "profile", "email", "groups", "offline_access"},
 	}
 	if cfg.AllowPrivateURLs {
 		// Inject an HTTP client that allows connections to private/internal IP
 		// ranges. Required when the Dex issuer URL is an internal DNS name that
 		// resolves to an RFC-1918 address (e.g. on a private management cluster).
 		// TLS verification is still enforced by this client.
 		dexCfg.HTTPClient = mcpoidc.NewPrivateIPAllowedHTTPClient(30 * time.Second)
 	}
 	provider, err := dex.NewProvider(dexCfg)
 	if err != nil {
 		return nil, nil, fmt.Errorf("oauth: create Dex provider: %w", err)
 	}

 	return newHandlerWithProvider(ctx, provider, cfg, logger)
 }

 // newHandlerWithProvider wires a pre-built provider into the mcp-oauth server.
 // It is separated from NewHandler so that tests can inject a mock provider
 // without requiring a live Dex instance.
 func newHandlerWithProvider(ctx context.Context, provider providers.Provider, cfg Config, logger *slog.Logger) (*handler.Handler, func(), error) {
 	store, cleanup, err := newStore(ctx, cfg, logger)
 	if err != nil {
 		return nil, nil, err
 	}

 	serverCfg := &mcpoauth.ServerConfig{
 		Issuer:                        cfg.Issuer,
 		AllowPublicClientRegistration: cfg.AllowPublicRegistration,
 		AllowRefreshTokenRotation:     true,
 		TrustedAudiences:              cfg.TrustedAudiences,
 	}

 	var opts []mcpoauth.ServerOption
 	if cfg.EncryptionKey != "" {
 		keyBytes, err := base64.StdEncoding.DecodeString(cfg.EncryptionKey)
 		if err != nil {
 			cleanup()
 			return nil, nil, fmt.Errorf("oauth: decode MCP_OAUTH_ENCRYPTION_KEY (must be base64): %w", err)
 		}
 		enc, err := security.NewEncryptor(keyBytes)
 		if err != nil {
 			cleanup()
 			return nil, nil, fmt.Errorf("oauth: create encryptor: %w", err)
 		}
 		opts = append(opts, mcpoauth.WithEncryptor(enc))
 	} else {
 		logger.Warn("MCP_OAUTH_ENCRYPTION_KEY is not set — OAuth tokens will be stored unencrypted. " +
 			"Set MCP_OAUTH_ENCRYPTION_KEY to a 64-hex-char AES-256 key for production use. " +
 			"Generate one with: openssl rand -hex 32")
 	}

 	srv, err := mcpoauth.NewServer(provider, store, store, store, serverCfg, logger, opts...)
 	if err != nil {
 		cleanup()
 		return nil, nil, fmt.Errorf("oauth: create server: %w", err)
 	}

 	return handler.New(srv, logger), cleanup, nil
 }

 // combinedStore is the set of store interfaces that a single backing store must
 // implement to be usable by the mcp-oauth server.
 type combinedStore interface {
 	storage.TokenStore
 	storage.ClientStore
 	storage.FlowStore
 }

 // newStore creates the token storage backend based on cfg.StorageType.
 func newStore(_ context.Context, cfg Config, _ *slog.Logger) (combinedStore, func(), error) {
 	if cfg.StorageType == storageTypeValkey {
 		return newValkeyStore(cfg)
 	}
 	// Default: in-process memory store (dev / single-replica).
 	s := memory.New()
 	return s, s.Stop, nil
 }

 // newValkeyStore creates a production Valkey storage backend.
 func newValkeyStore(cfg Config) (combinedStore, func(), error) {
 	if cfg.ValkeyURL == "" {
 		return nil, nil, fmt.Errorf("oauth: VALKEY_URL must be set when OAUTH_STORAGE=valkey")
 	}

 	vcfg := valkey.Config{
 		Address:  cfg.ValkeyURL,
 		Password: cfg.ValkeyPassword,
 	}
 	if cfg.ValkeyKeyPrefix != "" {
 		vcfg.KeyPrefix = cfg.ValkeyKeyPrefix
 	}
 	if cfg.ValkeyTLS {
 		vcfg.TLS = &tls.Config{MinVersion: tls.VersionTLS12}
 	}

 	s, err := valkey.New(vcfg)
 	if err != nil {
 		return nil, nil, fmt.Errorf("oauth: connect to Valkey at %s: %w", cfg.ValkeyURL, err)
 	}
 	return s, func() { s.Close() }, nil
 }

